function sha1(msgBytes) {
  function rotl(n, s) { return ((n << s) | (n >>> (32 - s))) >>> 0; }
  const ml = msgBytes.length * 8;
  const withOne = msgBytes.slice();
  withOne.push(0x80);
  while ((withOne.length % 64) !== 56) withOne.push(0);
  const hi = Math.floor(ml / 0x100000000);
  const lo = ml >>> 0;
  for (let i = 3; i >= 0; i--) withOne.push((hi >>> (i * 8)) & 0xff);
  for (let i = 3; i >= 0; i--) withOne.push((lo >>> (i * 8)) & 0xff);
  let h0 = 0x67452301, h1 = 0xEFCDAB89, h2 = 0x98BADCFE, h3 = 0x10325476, h4 = 0xC3D2E1F0;
  for (let i = 0; i < withOne.length; i += 64) {
    const w = new Array(80);
    for (let j = 0; j < 16; j++) {
      w[j] = ((withOne[i + j*4] << 24) | (withOne[i + j*4 + 1] << 16) | (withOne[i + j*4 + 2] << 8) | withOne[i + j*4 + 3]) >>> 0;
    }
    for (let j = 16; j < 80; j++) w[j] = rotl(w[j-3] ^ w[j-8] ^ w[j-14] ^ w[j-16], 1);
    let a = h0, b = h1, c = h2, d = h3, e = h4;
    for (let j = 0; j < 80; j++) {
      let f, k;
      if (j < 20) { f = ((b & c) | ((~b) & d)) >>> 0; k = 0x5A827999; }
      else if (j < 40) { f = (b ^ c ^ d) >>> 0; k = 0x6ED9EBA1; }
      else if (j < 60) { f = ((b & c) | (b & d) | (c & d)) >>> 0; k = 0x8F1BBCDC; }
      else { f = (b ^ c ^ d) >>> 0; k = 0xCA62C1D6; }
      const temp = (rotl(a, 5) + f + e + k + w[j]) >>> 0;
      e = d; d = c; c = rotl(b, 30); b = a; a = temp;
    }
    h0 = (h0 + a) >>> 0; h1 = (h1 + b) >>> 0; h2 = (h2 + c) >>> 0; h3 = (h3 + d) >>> 0; h4 = (h4 + e) >>> 0;
  }
  const out = [];
  for (const h of [h0, h1, h2, h3, h4]) {
    out.push((h >>> 24) & 0xff, (h >>> 16) & 0xff, (h >>> 8) & 0xff, h & 0xff);
  }
  return out;
}

function hmacSha1(keyBytes, msgBytes) {
  let k = keyBytes.slice();
  if (k.length > 64) k = sha1(k);
  while (k.length < 64) k.push(0);
  const oKey = k.map(b => b ^ 0x5c);
  const iKey = k.map(b => b ^ 0x36);
  return sha1(oKey.concat(sha1(iKey.concat(msgBytes))));
}

function generateTOTP(b32) {
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
  let bits = "";
  for (const ch of b32.toUpperCase().replace(/=+$/, "")) {
    const idx = alphabet.indexOf(ch);
    if (idx >= 0) bits += idx.toString(2).padStart(5, "0");
  }
  const key = [];
  for (let i = 0; i + 8 <= bits.length; i += 8) key.push(parseInt(bits.slice(i, i + 8), 2));
  let counter = Math.floor(Date.now() / 1000 / 30);
  const msg = [0, 0, 0, 0, 0, 0, 0, 0];
  for (let i = 7; i >= 0; i--) { msg[i] = counter & 0xff; counter = Math.floor(counter / 256); }
  const hmac = hmacSha1(key, msg);
  const offset = hmac[19] & 0x0f;
  const binCode = ((hmac[offset] & 0x7f) << 24) | ((hmac[offset+1] & 0xff) << 16) | ((hmac[offset+2] & 0xff) << 8) | (hmac[offset+3] & 0xff);
  return (binCode % 1000000).toString().padStart(6, "0");
}

