  });
  const tradeToken = r3.data.access_token;
  const [appPrefix, appType] = CFG.APP_ID.split('-');
  let r4;
  try {
    r4 = await ctx.helpers.httpRequest({
      method: 'POST', url: 'https://api-t1.fyers.in/api/v3/token',
      body: {
        fyers_id: CFG.FY_ID, app_id: appPrefix, redirect_uri: CFG.REDIRECT_URI,
        appType, code_challenge: '', state: 'n8n', scope: '', nonce: '',
        response_type: 'code', create_cookie: true
      },
      json: true, headers: { Authorization: `Bearer ${tradeToken}`, 'User-Agent': 'Mozilla/5.0' },
      returnFullResponse: true, ignoreHttpStatusErrors: true
    });
  } catch (e) { r4 = e.response || {}; }
