  const authCode = (String(urlStr).match(/[?&]auth_code=([^&]+)/) || [])[1];
  const appIdHash = 'dca98057da66c6b1c8ec0ac9e91db941da6ad2237b86ca8ba8e3ea69b9cac9cc';
