async function tgSend(ctx, method, body) {
  for (let attempt = 1; attempt <= 2; attempt++) {
    try {
      return await ctx.helpers.httpRequest({
        method: 'POST',
        url: `https://api.telegram.org/bot${CFG.TG_TOKEN}/${method}`,
        body,
        json: true,
        timeout: 8000
      });
    } catch (e) {
      if (attempt === 2) return { ok: false, error: String(e.message || e) };
    }
  }
}

