async function processTelegramUpdate(ctx, u) {
  if (!u || typeof u !== 'object') return;
  if (u.update_id) {
    state.last_update_id = Math.max(state.last_update_id || 0, u.update_id);
  }
  if (u.message && u.message.text && u.message.chat) {
    await handleCommand(ctx, String(u.message.chat.id), u.message.text.trim());
  } else if (u.callback_query) {
    const cb = u.callback_query;
    const chatId = String(cb.message.chat.id);
    const data = cb.data || '';
    await tgSend(ctx, 'answerCallbackQuery', { callback_query_id: cb.id });

    if (data.startsWith('simpler:')) {
      await sendCurrentStep(ctx, chatId, true);
    } else if (data.startsWith('qans:')) {
      const parts = data.split(':');
      await handleAnswer(ctx, chatId, parts[1], parts[2]);
    } else {
      await handleCommand(ctx, chatId, data);
    }
  }
}

