    function computeSimMetrics(s, cap, holdDays, podAPct) {
      const freqMult = 15 / Math.max(3, holdDays);
      const effectiveTrades = s.id === 'NIFTY' ? 1 : Math.round(s.tradesPerYr * freqMult);
      const dpPerSell = s.isEtfHeavy ? 5.50 : 15.93;
      const dpDragPct = ((effectiveTrades * dpPerSell) / cap) * 100;
      const sttDragPct = effectiveTrades * 0.12 * (s.isEtfHeavy ? 0.35 : 0.75);
      const totalFeeDragPct = Math.min(18.0, dpDragPct + sttDragPct);
      let regimeMult = 1.0, ddMult = 1.0;
      if (activeRegime === 'BULL') regimeMult = s.id === 'S4' || s.id === 'S2' || s.id === 'ENSEMBLE' ? 1.25 : 1.10;
      else if (activeRegime === 'CHOP') regimeMult = s.id === 'S3' ? 0.58 : (s.id === 'S2' || s.id === 'ENSEMBLE' ? 0.96 : 0.78);
      else if (activeRegime === 'CRASH') {
        regimeMult = s.id === 'S8' || s.id === 'ENSEMBLE' || s.id === 'S1' ? 0.92 : (s.id === 'NIFTY' ? -0.45 : 0.40);
        ddMult = s.id === 'NIFTY' ? 1.5 : (s.id === 'ENSEMBLE' || s.id === 'S8' ? 0.95 : 1.35);
      }
      let rawGross = s.grossCagr * regimeMult;
      if (s.id === 'ENSEMBLE') {
        const capBonus = cap >= 25000 ? 4.2 : (cap >= 12000 ? 2.4 : 0.6);
        rawGross = (12.0 + capBonus + (70 - podAPct) * 0.04) * regimeMult;
      }
      return { netCagr: +(rawGross - totalFeeDragPct).toFixed(2), feeDrag: +totalFeeDragPct.toFixed(2), maxDd: +(s.baseDd * ddMult).toFixed(2) };
    }

    function updateArena() {
