      const results = STRATEGIES.map(s => ({ ...s, sim: computeSimMetrics(s, cap, holdDays, podAPct) }));
      const sorted = [...results].sort((a, b) => b.sim.netCagr - a.sim.netCagr);
      const best = sorted[0];
      document.getElementById('kpiSimWinner').textContent = \`\${best.id} (\${best.sim.netCagr > 0 ? '+' : ''}\${best.sim.netCagr}%/yr)\`;
      document.getElementById('kpiSimSub').textContent = \`At ₹\${cap.toLocaleString('en-IN')} • \${holdDays}d Hold\`;

      const svg = document.getElementById('arenaEquitySvg');
      const W = 960, H = 320, padL = 75, padR = 135, padT = 26, padB = 34;
      const plotW = W - padL - padR, plotH = H - padT - padB, steps = 20;
      const curves = results.filter(r => r.active).map(r => {
        const pts = []; let w = cap; const qRate = (r.sim.netCagr / 100) / 4;
        for (let q = 0; q <= steps; q++) {
          if (q > 0) w = w * (1 + qRate + Math.sin(q * 0.9 + (r.id.charCodeAt(0) % 5)) * (r.sim.maxDd * 0.0022));
          pts.push(w);
        }
        return { ...r, pts, finalW: w };
      });
      const allVals = curves.length ? curves.flatMap(c => c.pts) : [cap, cap * 1.5];
      const minW = Math.min(...allVals) * 0.96, maxW = Math.max(...allVals) * 1.04;
      const xOf = q => padL + (q / steps) * plotW, yOf = v => padT + (1 - (v - minW) / Math.max(1, maxW - minW)) * plotH;

      let out = '';
      for (let g = 0; g <= 4; g++) {
        const gv = minW + (g / 4) * (maxW - minW), gy = yOf(gv);
        out += \`<line x1="\${padL}" y1="\${gy}" x2="\${W - padR}" y2="\${gy}" stroke="rgba(255,255,255,0.08)" stroke-dasharray="3,3"/>\`;
        out += \`<text x="\${padL - 8}" y="\${gy + 4}" fill="#94a3b8" font-size="11" text-anchor="end" font-family="JetBrains Mono">₹\${Math.round(gv).toLocaleString('en-IN')}</text>\`;
      }
      curves.forEach(c => {
        const poly = c.pts.map((v, q) => \`\${xOf(q)},\${yOf(v)}\`).join(' ');
        out += \`<polyline fill="none" stroke="\${c.color}" stroke-width="\${c.width}" points="\${poly}"/>\`;
        const lastY = yOf(c.finalW);
        out += \`<circle cx="\${xOf(steps)}" cy="\${lastY}" r="4" fill="\${c.color}"/>\`;
        out += \`<text x="\${W - padR + 8}" y="\${lastY + 4}" fill="\${c.color}" font-size="11" font-weight="700" font-family="JetBrains Mono">\${c.id}: ₹\${Math.round(c.finalW).toLocaleString('en-IN')}</text>\`;
      });
      svg.innerHTML = out;
      document.getElementById('arenaInsightBanner').innerHTML = \`🏆 <strong>Live Simulation Verdict at ₹\${cap.toLocaleString('en-IN')} (\${holdDays}d hold, \${activeRegime}):</strong> <strong>\${best.name}</strong> leads with <strong>+\${best.sim.netCagr}% Net CAGR</strong> and <strong>-\${best.sim.maxDd}% Max Drawdown</strong>.\`;

