      html += \`<line x1="\${padL}" y1="\${yOf(d.atrStop)}" x2="\${W - padR}" y2="\${yOf(d.atrStop)}" stroke="#f59e0b" stroke-width="2" stroke-dasharray="6,4"/>\`;
      html += \`<polyline fill="none" stroke="#38bdf8" stroke-width="3" points="\${d.prices.map((v, i) => \`\${xOf(i)},\${yOf(v)}\`).join(' ')}"/>\`;
      const bx = xOf(d.buyIdx), by = yOf(d.buyPrice);
      html += \`<circle cx="\${bx}" cy="\${by}" r="8" fill="#10b981" stroke="#fff" stroke-width="2"/>\`;
      html += \`<text x="\${bx}" y="\${by - 14}" fill="#6ee7b7" font-size="11" font-weight="700" text-anchor="middle">🟢 BUY ₹\${d.buyPrice}</text>\`;
      svg.innerHTML = html;
      document.getElementById('signalExplainBox').innerHTML = simpleChartMode ? d.simpleStory : d.proStory;
    }

