      document.getElementById('topMasteryVal').textContent = \`\${totalDrills} / 20 Drills (\${Math.round(totalDrills * 5)}%)\`;

      const alertBox = document.getElementById('reinforceQueueAlert');
      if (reinforceState.missed && reinforceState.missed.length) {
        alertBox.innerHTML = \`⚠️ <strong>Spaced-Repetition Due Queue:</strong> Concepts <strong>\${reinforceState.missed.join(', ')}</strong> need reinforcement! Click them below to retry.\`;
      } else {
        alertBox.innerHTML = \`✅ <strong>Zero Missed Concepts in Queue!</strong> Complete Round 1 + Round 2 on each concept below to reach 20/20 Reinforced Mastery.\`;
