      const list = document.getElementById('reinforceTrackerList');
      list.innerHTML = LESSONS.map((l, idx) => {
        const p1 = !!(reinforceState.r1 && reinforceState.r1[l.id]);
        const p2 = !!(reinforceState.r2 && reinforceState.r2[l.id]);
        const status = p1 && p2 ? '🏆 Reinforced (2/2)' : (p1 || p2 ? '⏳ In Progress (1/2)' : '🔒 Not Started (0/2)');
