              <td><span class="pill \${e.status === 'success' ? 'pill-emerald' : 'pill-crimson'}">\${String(e.status).toUpperCase()}</span></td>
              <td class="mono">\${e.mode}</td>
              <td class="mono">\${e.startedAt ? e.startedAt.replace('T', ' ').slice(0, 19) : '-'}</td>
              <td class="mono">\${e.stoppedAt ? e.stoppedAt.replace('T', ' ').slice(0, 19) : 'Running'}</td>
            </tr>
          \`).join('');
        }
      } catch (err) {
        tbody.innerHTML = '<tr><td colspan="5">Error fetching live state.</td></tr>';
